#include <iostream>
#include "so101_gazebo_demo/pick_place/runner.hpp"
using namespace so101_gazebo_demo::pick_place;
int main(int argc,char ** argv) { RunRequest request; for(int i=1;i<argc;++i) { const std::string a=argv[i]; if(a=="--mode"&&i+1<argc) { auto m=runModeFromString(argv[++i]); if(!m){std::cerr<<"invalid mode\n";return 2;} request.mode=*m; } else if(a=="--fail-at"&&i+1<argc) { auto s=stateFromString(argv[++i]); if(!s){std::cerr<<"invalid state\n";return 2;} request.fail_at=*s; } else if(a=="--stop-after"&&i+1<argc) { auto s=stateFromString(argv[++i]); if(!s){std::cerr<<"invalid state\n";return 2;} request.stop_after=*s; } else if(a=="--resume") request.resume=true; else { std::cerr<<"usage: pick_place_state_machine [--mode dry_run|plan_only|execute] [--fail-at STATE] [--stop-after STATE] [--resume]\n"; return 2; } } StateMachineRunner runner; const auto r=runner.run(request); std::cout<<"status="<<toString(r.status)<<"\ntrace="; for(size_t i=0;i<r.state_trace.size();++i) std::cout<<(i?" -> ":"")<<toString(r.state_trace[i]); std::cout<<"\n"; if(r.failure) std::cout<<"failure="<<r.failure->code<<"\n"; return r.status==RunStatus::ERROR?1:0; }
